INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_2_72',
  'What is the primary benefit of deploying an Amazon RDS database instance as Multi-AZ?',
  'mcq',
  '["It provides automatic failover to a synchronous standby replica in a different Availability Zone.","It allows the standby replica to serve read traffic for improved performance.","It reduces database licensing costs by sharing resources across multiple Availability Zones.","It enables manual scaling of compute and storage independently across Availability Zones."]'::json,
  '{0}',
  'Option A (correct) states that Multi-AZ deployment for Amazon RDS provides automatic failover to a synchronous standby replica in a different Availability Zone, ensuring high availability during an outage. Option B is incorrect because the standby replica in a Multi-AZ deployment is for failover only and does not serve read traffic; read replicas are used for read scaling. Option C is incorrect as Multi-AZ deployment typically increases cost due to duplicated resources, not reduces it. Option D is incorrect as Multi-AZ is for availability, not independent manual scaling of compute and storage.',
  NOW(),
  'quiz_domain19_4',
  NOW(),
  1,
  NULL,
  NULL,
  'm_19_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_2_73',
