INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_1_109',
  'A developer needs to create a serverless API endpoint that triggers an AWS Lambda function. Which AWS service should be used to expose this Lambda function as a RESTful API?',
