INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_1_111',
  'Which AWS service is designed to provide content delivery network (CDN) capabilities for improved performance and reduced latency for end-users globally?',
