INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_1_123',
  'A developer is building an event-driven application where a producer service publishes messages that need to be processed by multiple independent consumer services. Which AWS service should be used to fan out these messages efficiently?',
