INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_4_52',
  'A company wants to securely connect its on-premises data center to its AWS VPC over a private, dedicated network connection. Which service should they use?',
