INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_1_44',
  'What is Amazon S3 primarily used for?',
  'mcq',
  '["Highly scalable object storage for various data types","Relational database management","Block storage for EC2 instances","Shared file system for multiple EC2 instances"]'::json,
  '{0}',
  'Option A (correct) describes Amazon S3 (Simple Storage Service), which provides highly scalable, durable, and available object storage for a wide range of use cases. Option B describes Amazon RDS. Option C describes Amazon EBS. Option D describes Amazon EFS.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  54,
