INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_5_57',
  'A company needs to transfer 200 TB of data from their on-premises data center to Amazon S3. Their internet connection is slow and unreliable, making network transfer impractical. Which AWS service is designed for offline data transfer of large datasets?',
  'mcq',
