INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_4_89',
  'A company operates a global e-commerce platform with users across multiple continents. They need to ensure low-latency access for both static and dynamic content, and improve the overall performance and availability of their application endpoints. Which two AWS services should they implement? (Select TWO.)',
