INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_1_70',
  'A company needs shared file storage that can be accessed concurrently by multiple Amazon EC2 instances. Which AWS storage services meet this requirement? (Select TWO.)',
