INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_1_105',
  'A security administrator needs to create a new IAM user with permissions to manage a specific Amazon S3 bucket. Arrange the following steps to apply the principle of least privilege.',
  'ordering',
  '["Create a custom IAM policy that defines specific S3 bucket actions.","Attach a policy to the IAM user that grants permissions only to the specific S3 bucket.","Test the user''s permissions to ensure they can only access the intended S3 bucket.","Create a new IAM user."]'::json,
  '{3,0,1,2}'::int[],
  'To apply the principle of least privilege, the first step (Option D) is to create the IAM user. Next, a custom IAM policy (Option A) should be created to define only the necessary S3 bucket actions. Then, this policy (Option B) is attached to the IAM user. Finally, the permissions (Option C) should be tested to confirm the user can only perform the intended actions on the specific S3 bucket, ensuring least privilege.',
  NOW(),
  'quiz_domain_18_4',
  NOW(),
  1,
  NULL,
  NULL,
  'm_18_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
