) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_117',
  'Match each compute scaling mechanism to its primary purpose.',
  'matching',
  '{"A":"EC2 Auto Scaling","B":"AWS Auto Scaling","C":"Amazon CloudWatch"}'::json,
  NULL,
  'EC2 Auto Scaling (Option A) automatically adjusts the number of Amazon EC2 instances in a group based on defined policies, scaling capacity up or down to meet demand. AWS Auto Scaling (Option B) extends this concept to automate scaling for multiple AWS services beyond just EC2, such as Amazon DynamoDB, Amazon ECS, and Amazon Aurora. Amazon CloudWatch (Option C) is a monitoring service that collects metrics, logs, and events, and can trigger alarms and scaling actions for various AWS services, including Auto Scaling.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  2,
  '{"left":["EC2 Auto Scaling","AWS Auto Scaling","Amazon CloudWatch"],"right":["Adjust EC2 capacity based on demand","Automate scaling for multiple services","Monitor resources and trigger scaling actions"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

