INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_119',
  'Match the compute concept to its definition.',
  'matching',
  '{"A":"Spot Instances","B":"On-Demand Instances","C":"Reserved Instances"}'::json,
  NULL,
  'Spot Instances (Option A) allow customers to bid on unused Amazon EC2 capacity, offering significant cost savings but with the risk of interruption. On-Demand Instances (Option B) allow customers to pay for compute capacity by the hour or second without long-term commitments. Reserved Instances (Option C) offer a significant discount (up to 75%) compared to On-Demand pricing in exchange for committing to a 1-year or 3-year term.',
