  'quiz_domain20_4',
  NOW(),
  4,
  '{"left":["Spot Instances","On-Demand Instances","Reserved Instances"],"right":["Unused EC2 capacity, significant savings, can be interrupted","Pay for compute capacity by the hour or second","Commit to 1- or 3-year term for significant discount"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
