INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_121',
  'Match the AWS service to its primary use for container orchestration.',
  'matching',
  '{"A":"Amazon ECS","B":"Amazon EKS","C":"Amazon Fargate"}'::json,
  NULL,
  'Amazon ECS (Option A) is a fully managed container orchestration service that makes it easy to deploy, manage, and scale containerized applications. Amazon EKS (Option B) is a fully managed Kubernetes service that allows running Kubernetes on AWS without needing to install, operate, and maintain your own Kubernetes control plane. Amazon Fargate (Option C) is a serverless compute engine that works with both Amazon ECS and Amazon EKS, allowing you to run containers without managing servers or clusters.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  6,
  '{"left":["Amazon ECS","Amazon EKS","Amazon Fargate"],"right":["Managed container orchestration service","Managed Kubernetes service","Serverless compute engine for containers"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_122',
  'Match each AWS compute service to its primary characteristic.',
  'matching',
  '{"A":"Amazon EC2","B":"AWS Lambda","C":"Amazon Fargate","D":"AWS Batch"}'::json,
  NULL,
  'Amazon EC2 provides virtual servers (instances) giving users full control over the operating system and software. AWS Lambda enables running code without provisioning or managing servers, executing functions in response to events. Amazon Fargate is a serverless compute engine for containers, eliminating the need to manage EC2 instances. AWS Batch allows running batch computing workloads on AWS, dynamically provisioning compute resources.',
