INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_125',
  'Match the compute scaling concept to its description.',
  'matching',
  '{"A":"EC2 Auto Scaling","B":"Target Tracking Scaling","C":"Scheduled Scaling"}'::json,
  NULL,
  'EC2 Auto Scaling dynamically adjusts the number of EC2 instances in an Auto Scaling group to maintain application availability and allows scaling capacity up or down automatically. Target Tracking Scaling adjusts capacity to keep a metric (e.g., CPU utilization) at a specified target value. Scheduled Scaling allows you to set up a schedule for Auto Scaling to scale your application in response to predictable load changes.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  10,
  '{"left":["EC2 Auto Scaling","Target Tracking Scaling","Scheduled Scaling"],"right":["Dynamically adjusts EC2 instance count","Scales based on a metric target","Scales based on predictable load changes"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_126',
  'Match each AWS compute service to its primary characteristic for deploying containerized applications with varying operational overhead requirements.',
  'matching',
  '{"A":"AWS Fargate","B":"Amazon ECS on EC2","C":"AWS Lambda"}'::json,
  NULL,
  'AWS Fargate (Option A) provides a serverless compute engine for containers, abstracting away the underlying EC2 instance management, making it ideal for teams seeking zero infrastructure management. Amazon ECS on EC2 (Option B) offers container orchestration but requires the user to provision, scale, and maintain the underlying EC2 instances, leading to higher operational overhead. AWS Lambda (Option C) is an event-driven serverless compute service primarily for functions, not typically for long-running containerized applications, and has a hard 15-minute execution limit, making it unsuitable for many container workloads.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  11,
  '{"left":["AWS Fargate","Amazon ECS on EC2","AWS Lambda"],"right":["Serverless container compute with zero infrastructure management.","Container orchestration requiring EC2 instance management.","Event-driven serverless compute with a 15-minute execution limit."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'hard'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_127',
  'Match the AWS compute service to its primary advantage when considering infrastructure management and cost for containerized applications.',
  'matching',
  '{"A":"Amazon ECS on Fargate","B":"Amazon ECS on EC2","C":"Amazon EC2"}'::json,
  NULL,
  'Amazon ECS on Fargate (Option A) offers a serverless compute engine for Amazon ECS, allowing users to run containers without provisioning or managing servers, thus providing zero server management. Amazon ECS on EC2 (Option B) provides container orchestration but requires users to manage the underlying EC2 instances, offering fine-grained control over the compute environment but increasing operational overhead. Amazon EC2 (Option C) provides raw virtual servers, offering the most control over the compute environment but requiring manual management of instances, including scaling, patching, and capacity planning.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  12,
  '{"left":["Amazon ECS on Fargate","Amazon ECS on EC2","Amazon EC2"],"right":["Zero server management for container workloads.","Fine-grained control over EC2 instances for container hosts.","Direct control over virtual servers with manual scaling."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'hard'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
