  '{"left":["Lambda''s 15-minute timeout","Fargate''s serverless model","EC2''s instance types"],"right":["Best for short, event-driven, stateless functions.","Ideal for containerized microservices without server management.","Provides customizable CPU, memory, and GPU for specific needs."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_2',
  'hard'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
