INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_2_130',
  'Match the AWS compute service to the scenario where it provides the most cost-effective solution for specific workload patterns.',
  'matching',
  '{"A":"Spot Instances","B":"AWS Lambda","C":"Amazon EC2 Reserved Instances"}'::json,
  NULL,
