  '{"left":["S3 Standard","S3 Standard-IA","S3 Glacier Deep Archive"],"right":["High durability, frequently accessed, low latency","High durability, infrequently accessed, rapid retrieval","Lowest cost, long-term archive, retrieval in hours"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

