INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_3_91',
  'Match each AWS database service to its primary database model.',
  'matching',
  '{"A":"Amazon RDS","B":"Amazon DynamoDB","C":"Amazon Aurora"}'::json,
  NULL,
  'Amazon RDS (Relational Database Service) (Option A) is a managed service that makes it easy to set up, operate, and scale a relational database in the cloud. Amazon DynamoDB (Option B) is a fast and flexible NoSQL database service for all applications that need consistent, single-digit millisecond latency at any scale, supporting key-value and document data models. Amazon Aurora (Option C) is a MySQL and PostgreSQL-compatible relational database built for the cloud, combining the performance and availability of traditional enterprise databases with the simplicity and cost-effectiveness of open-source databases.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  54,
  '{"left":["Amazon RDS","Amazon DynamoDB","Amazon Aurora"],"right":["Managed relational database","Managed NoSQL key-value/document database","MySQL/PostgreSQL compatible relational database"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_3_92',
  'Match the database feature to its primary purpose.',
  'matching',
  '{"A":"Read Replicas","B":"Multi-AZ Deployment","C":"RDS Proxy"}'::json,
  NULL,
  'Read Replicas (Option A) are used to improve read scalability and performance by offloading read traffic from the primary database instance. Multi-AZ Deployment (Option B) enhances database availability and fault tolerance by synchronously replicating data to a standby instance in a different Availability Zone. RDS Proxy (Option C) is a fully managed, highly available database proxy that makes applications more resilient to database failures and helps manage database connections efficiently.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  55,
  '{"left":["Read Replicas","Multi-AZ Deployment","RDS Proxy"],"right":["Improve read scalability and performance","Enhance database availability and fault tolerance","Manage and pool database connections"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_3_93',
  'Match the caching service to its primary use case.',
  'matching',
  '{"A":"Amazon ElastiCache for Redis","B":"Amazon ElastiCache for Memcached","C":"Amazon DynamoDB Accelerator (DAX)"}'::json,
  NULL,
  'Amazon ElastiCache for Redis (Option A) is suitable for use cases requiring advanced data structures, pub/sub capabilities, and geospatial indexing. Amazon ElastiCache for Memcached (Option B) is a simpler, high-performance, distributed memory object caching system, ideal for simple key-value caching and multi-threaded applications. Amazon DynamoDB Accelerator (DAX) (Option C) is a fully managed, highly available, in-memory cache for DynamoDB tables that delivers up to a 10x performance improvement for read-heavy workloads.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  56,
  '{"left":["Amazon ElastiCache for Redis","Amazon ElastiCache for Memcached","Amazon DynamoDB Accelerator (DAX)"],"right":["Advanced data structures, pub/sub, geospatial","Simple key-value caching, multi-threaded","In-memory cache for DynamoDB tables"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_3_94',
  'Match the database type to its characteristic.',
  'matching',
  '{"A":"Relational Database","B":"NoSQL Database","C":"Data Warehouse"}'::json,
  NULL,
  'A Relational Database (Option A) stores structured data in tables with predefined schemas, supports ACID transactions, and allows complex joins. A NoSQL Database (Option B) offers flexible schemas, high scalability, and is optimized for specific data models like key-value or document stores. A Data Warehouse (Option C), such as Amazon Redshift, is optimized for analytical processing of large datasets, enabling complex queries for business intelligence.',
