  57,
  '{"left":["Relational Database","NoSQL Database","Data Warehouse"],"right":["Structured data, ACID transactions, joins","Flexible schema, high scalability, key-value/document","Analytical processing, large datasets, complex queries"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_20_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

