INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_20_m_20_3_105',
  'Match the AWS database feature to its primary benefit for ensuring high availability and disaster recovery.',
  'matching',
  '{"A":"Amazon RDS Multi-AZ deployments","B":"Amazon Aurora Global Database","C":"DynamoDB Global Tables"}'::json,
  NULL,
  'Amazon RDS Multi-AZ deployments (Option A) provide high availability by automatically provisioning and maintaining a synchronous standby replica in a different Availability Zone, enabling automatic failover in case of primary instance failure. Amazon Aurora Global Database (Option B) is designed for fast disaster recovery across AWS Regions, providing a single Aurora database that spans multiple regions with low-latency global reads. DynamoDB Global Tables (Option C) offer multi-Region, multi-master replication for DynamoDB tables, enabling fast, local reads and writes for globally distributed applications and disaster recovery.',
  NOW(),
  'quiz_domain20_4',
  NOW(),
  68,
