INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_2_115',
  'A company is migrating various applications to AWS and needs to select appropriate compute purchasing options for different workload types to optimize costs. Match the workload characteristic to the MOST cost-effective EC2 purchasing option.',
  'matching',
  '{"A":"Predictable, long-term, steady-state workload","B":"Flexible, fault-tolerant, non-critical workload","C":"Consistent compute usage, flexible instance family"}'::json,
  NULL,
  'For a predictable, long-term, steady-state workload (Option A), EC2 Reserved Instances offer significant discounts in exchange for a 1-year or 3-year commitment. For flexible, fault-tolerant, non-critical workloads (Option B), EC2 Spot Instances provide the deepest discounts but can be interrupted. For consistent compute usage with flexibility across instance families (Option C), AWS Savings Plans offer discounts based on a commitment to spend a certain amount per hour.',
