  'quiz_domain21_4',
  NOW(),
  15,
  '{"left":["Predictable, long-term, steady-state workload","Flexible, fault-tolerant, non-critical workload","Consistent compute usage, flexible instance family"],"right":["EC2 Reserved Instances","EC2 Spot Instances","AWS Savings Plans"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_21_2',
  'hard'
) ON CONFLICT (id) DO NOTHING;

