INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_3_101',
  'Match the Amazon DynamoDB capacity mode to its ideal use case for cost efficiency.',
  'matching',
  '{"A":"Provisioned capacity mode","B":"On-demand capacity mode"}'::json,
  NULL,
  'Provisioned capacity mode (left: 0) is ideal for workloads with predictable and consistent traffic (right: 0) because you specify the read and write capacity units upfront, which can be more cost-effective for steady-state usage. On-demand capacity mode (left: 1) is best suited for workloads with unpredictable or spiky traffic patterns (right: 1) as it automatically scales capacity and charges only for the actual reads and writes, eliminating the need for capacity planning and preventing throttling.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
