INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_3_103',
  'Match the database scaling method to its cost optimization benefit.',
  'matching',
  '{"A":"Horizontal Scaling (e.g., Read Replicas)","B":"Vertical Scaling (e.g., larger instance type)","C":"Serverless Scaling (e.g., Aurora Serverless v2)"}'::json,
  NULL,
  'Horizontal Scaling (e.g., Read Replicas) (left: 0) distributes load across multiple instances, improving performance and availability for reads (right: 1), which can be more cost-effective than a single large instance for read-heavy workloads. Vertical Scaling (e.g., larger instance type) (left: 1) increases the resources of a single instance, which is simpler but has limits and higher cost for idle capacity (right: 2). Serverless Scaling (e.g., Aurora Serverless v2) (left: 2) provides capacity on demand, paying only for consumption, ideal for intermittent loads (right: 0), offering significant cost savings by automatically scaling down during idle periods.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  28,
  '{"left":["Horizontal Scaling (e.g., Read Replicas)","Vertical Scaling (e.g., larger instance type)","Serverless Scaling (e.g., Aurora Serverless v2)"],"right":["Provides capacity on demand, paying only for consumption, ideal for intermittent loads","Distributes load across multiple instances, improving performance and availability for reads","Increases resources of a single instance, simpler but has limits and higher cost for idle"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_21_3',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
