INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_4_92',
  'Match each network service to its private connectivity type.',
  'matching',
  '{"A":"AWS Direct Connect","B":"AWS VPN","C":"VPC Endpoints"}'::json,
  NULL,
  'AWS Direct Connect (left 0) provides a dedicated network connection from an on-premises data center to AWS. AWS VPN (left 1) establishes an encrypted tunnel over the public internet to connect on-premises networks to AWS. VPC Endpoints (left 2) enable private access to supported AWS services and VPC endpoint services powered by AWS PrivateLink, keeping traffic within the AWS network.',
