  '{"left":["VPC Gateway Endpoints for S3/DynamoDB","S3 Transfer Acceleration","NAT Gateway"],"right":["Optimizes data transfer speeds for uploads from distant locations","Enables instances in private subnets to access the internet, incurring data processing charges","Allows private subnet access to S3/DynamoDB without NAT Gateway, incurring no data processing charges"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_21_4',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_4_95',
