INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_1_80',
  'Match each Amazon S3 storage class to its typical access pattern.',
  'matching',
  '{"A":"Amazon S3 Standard","B":"S3 Intelligent-Tiering","C":"Amazon S3 Glacier"}'::json,
  NULL,
  'Amazon S3 Standard (left 0) is designed for frequently accessed data that requires high durability and availability. S3 Intelligent-Tiering (left 1) is ideal for data with unknown or changing access patterns, as it automatically moves objects between access tiers to optimize costs. Amazon S3 Glacier (left 2) is a low-cost storage class optimized for archival data that is rarely accessed.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  54,
  '{"left":["Amazon S3 Standard","S3 Intelligent-Tiering","Amazon S3 Glacier"],"right":["Frequently accessed data","Unknown or changing access","Archival data"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_21_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_1_81',
  'Match each AWS storage service to its primary use case.',
  'matching',
  '{"A":"Amazon S3","B":"Amazon EBS","C":"Amazon EFS"}'::json,
  NULL,
  'Amazon S3 (left 0) is an object storage service suitable for data lakes, backups, and static website hosting. Amazon EBS (left 1) provides persistent block storage volumes for use with Amazon EC2 instances. Amazon EFS (left 2) offers a scalable, elastic, shared file system for use with Amazon EC2 instances, accessible by multiple instances simultaneously.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  55,
