INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_1_135',
  'Match each AWS IAM concept to its primary security function.',
  'matching',
  '{"A":"AWS IAM Role","B":"Long-term Access Key","C":"AWS IAM Identity Center"}'::json,
  NULL,
  'An AWS IAM Role (left[0]) is designed to provide temporary credentials to AWS services and resources, such as an Amazon EC2 instance, without embedding static credentials, making ''Temporary credentials for EC2'' (right[1]) the correct match. Long-term Access Keys (left[1]) are static credentials that, if embedded directly into application code, pose a significant security risk due to potential exposure and difficulty in rotation, matching with ''Static credentials in code'' (right[2]). AWS IAM Identity Center (left[2]) provides a centralized service for managing single sign-on (SSO) access to multiple AWS accounts and business applications, aligning with ''Centralized access management'' (right[0]).',
  NOW(),
  'quiz_domain_18_4',
