INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_2_131',
  'Match the AWS networking component to its primary connectivity purpose.',
  'matching',
  '{"A":"VPC Endpoint","B":"AWS PrivateLink","C":"NAT Gateway"}'::json,
  NULL,
  'A VPC Endpoint (left[0]) enables ''Private service access'' (right[0]) to AWS services like Amazon S3 or DynamoDB from within a VPC without traversing the internet. AWS PrivateLink (left[1]) provides ''Private connectivity to services'' (right[2]) hosted by AWS, by other AWS accounts, or by SaaS partners, keeping network traffic within the AWS network. A NAT Gateway (left[2]) allows instances in a private subnet to establish ''Outbound internet access'' (right[1]) while preventing unsolicited inbound connections from the internet.',
  NOW(),
  'quiz_domain_18_4',
  NOW(),
  24,
  '{"left":["VPC Endpoint","AWS PrivateLink","NAT Gateway"],"right":["Private service access","Outbound internet access","Private connectivity to services"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_18_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_2_132',
  'Match the AWS service to its role in monitoring or controlling network traffic.',
  'matching',
  '{"A":"Security Group","B":"Network ACL","C":"Amazon VPC Flow Logs"}'::json,
  NULL,
  'A Security Group (left[0]) performs ''Stateful packet filtering'' (right[1]), meaning it remembers previous connections and automatically allows return traffic. A Network ACL (left[1]) provides ''Stateless packet filtering'' (right[0]), requiring explicit rules for both inbound and outbound traffic. Amazon VPC Flow Logs (left[2]) capture detailed information about ''IP traffic recording'' (right[2]) going to and from network interfaces in a VPC, useful for monitoring and troubleshooting.',
  NOW(),
  'quiz_domain_18_4',
  NOW(),
  25,
  '{"left":["Security Group","Network ACL","Amazon VPC Flow Logs"],"right":["Stateless packet filtering","Stateful packet filtering","IP traffic recording"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_18_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

