  '{"left":["VPC Endpoints","AWS PrivateLink","AWS Certificate Manager"],"right":["Private access to AWS services","Private connectivity to SaaS","Managed TLS certificates"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
