  37,
  '{"left":["AWS Systems Manager Session Manager","Bastion Host","Security Group Rule (0.0.0.0/0 on port 22)"],"right":["Jump server for SSH","Insecure SSH access","Browser-based shell access"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_18_2',
  'hard'
) ON CONFLICT (id) DO NOTHING;

