INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_3_121',
  'Match the AWS encryption service to its key management characteristic.',
  'matching',
  '{"A":"AWS KMS","B":"AWS CloudHSM","C":"SSE-S3"}'::json,
  NULL,
  'AWS KMS (left[0]) provides ''Managed encryption keys'' (right[2]) that you can control, integrate with other AWS services, and audit. AWS CloudHSM (left[1]) offers ''Dedicated hardware security'' (right[1]) modules (HSMs) in the AWS cloud, giving you exclusive control over your encryption keys. SSE-S3 (left[2]) uses ''AWS-managed keys'' (right[0]) for server-side encryption of objects in Amazon S3, where AWS handles key creation, management, and rotation.',
  NOW(),
  'quiz_domain_18_4',
  NOW(),
  41,
  '{"left":["AWS KMS","AWS CloudHSM","SSE-S3"],"right":["AWS-managed keys","Dedicated hardware security","Managed encryption keys"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_18_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_18_m_18_3_122',
  'Match the Amazon S3 data protection feature to its primary purpose.',
  'matching',
  '{"A":"S3 Versioning","B":"S3 Object Lock","C":"S3 Lifecycle Policy"}'::json,
  NULL,
  'S3 Versioning (left[0]) allows you to ''Recover previous versions'' (right[2]) of objects, protecting against accidental deletions or overwrites. S3 Object Lock (left[1]) provides ''WORM compliance'' (Write Once, Read Many) (right[0]) by preventing objects from being deleted or overwritten for a fixed amount of time or indefinitely. An S3 Lifecycle Policy (left[2]) enables ''Automated object tiering'' (right[1]) and deletion, moving objects between storage classes or expiring them after a set period.',
  NOW(),
  'quiz_domain_18_4',
  NOW(),
  42,
  '{"left":["S3 Versioning","S3 Object Lock","S3 Lifecycle Policy"],"right":["WORM compliance","Automated object tiering","Recover previous versions"]}'::json,
