INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_19_m_19_2_167',
  'Match the Amazon RDS feature to its primary use case for resilience or performance.',
  'matching',
  '{"A":"Amazon RDS Multi-AZ Deployments","B":"Amazon RDS Read Replicas"}'::json,
  NULL,
  'Amazon RDS Multi-AZ Deployments (left item 0) are primarily used to provide high availability and automatic failover for relational databases by synchronously replicating data to a standby instance in a different Availability Zone. The standby instance does not serve read traffic. Amazon RDS Read Replicas (left item 1), on the other hand, are designed to enhance read performance and offload read queries from the primary database instance by providing asynchronously replicated copies that can serve read traffic. This distinction is important, as confusing Multi-AZ standby with read replicas (anti-pattern ap-2.2-001) is a common misconception.',
  NOW(),
  'quiz_domain19_4',
  NOW(),
  9,
  '{"left":["Amazon RDS Multi-AZ Deployments","Amazon RDS Read Replicas"],"right":["Enhance read performance and offload queries","Provide high availability and automatic failover"]}'::json,
  '{"left":[0,1],"right":[0,1]}'::jsonb,
  'm_19_2',
  'medium'
) ON CONFLICT (id) DO NOTHING;

