INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_2_118',
  'Match each AWS compute purchasing option to its primary use case for cost optimization.',
  'matching',
  '{"A":"EC2 Spot Instances","B":"EC2 Reserved Instances","C":"AWS Savings Plans"}'::json,
  NULL,
