INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_2_120',
  'Match each compute optimization strategy to its cost-saving benefit.',
  'matching',
  '{"A":"Right-sizing instances","B":"Auto Scaling","C":"Graviton instances"}'::json,
  NULL,
  'Right-sizing instances (left: 0) involves analyzing workload performance and resource utilization to select the most appropriate and cost-effective Amazon EC2 instance type and size, avoiding over-provisioning. Auto Scaling (left: 1) automatically adjusts the number of EC2 instances in your application to maintain performance and reduce costs by scaling out during peak demand and scaling in during idle periods. Graviton instances (left: 2), powered by AWS-designed ARM-based processors, offer up to 40% better price/performance over comparable x86 instances for a wide range of workloads.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  3,
  '{"left":["Right-sizing instances","Auto Scaling","Graviton instances"],"right":["Matching instance to workload needs","Adjusting capacity based on demand","Improved price/performance for compatible workloads"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_21_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

