INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_3_112',
  'Match each database cost optimization feature to its ideal use case.',
  'matching',
  '{"A":"Aurora Serverless v2","B":"DynamoDB On-Demand","C":"RDS Read Replicas"}'::json,
  NULL,
  'Aurora Serverless v2 (left: 0) is designed for intermittent, spiky, or unpredictable workloads, automatically scaling capacity in fine-grained increments and scaling down to minimal ACUs during idle periods to save costs. DynamoDB On-Demand (left: 1) is a flexible billing option for DynamoDB that allows you to pay for only the read and write requests your application performs, making it ideal for variable and unpredictable traffic patterns. RDS Read Replicas (left: 2) provide an elastic way to scale out beyond the capacity of a single database instance for read-heavy database workloads, improving performance and reducing the load on the primary instance.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  16,
  '{"left":["Aurora Serverless v2","DynamoDB On-Demand","RDS Read Replicas"],"right":["Intermittent or unpredictable workloads","Variable and unpredictable traffic patterns","Offloading read-heavy database traffic"]}'::json,
