INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_21_m_21_3_113',
  'Match each AWS service or concept to its role in database cost optimization.',
  'matching',
  '{"A":"Amazon ElastiCache","B":"Amazon RDS Proxy","C":"Data retention policies"}'::json,
  NULL,
  'Amazon ElastiCache (left: 0) provides in-memory caching to significantly reduce database load and improve application response times by storing frequently accessed data closer to the application. Amazon RDS Proxy (left: 1) is a fully managed, highly available database proxy that makes applications more resilient to database failures and more secure, by efficiently managing database connections and reducing connection overhead. Data retention policies (left: 2) define how long data should be kept, allowing for automated archiving or deletion of old, infrequently accessed data to reduce storage costs.',
  NOW(),
  'quiz_domain21_4',
  NOW(),
  17,
  '{"left":["Amazon ElastiCache","Amazon RDS Proxy","Data retention policies"],"right":["In-memory caching to reduce database load","Efficiently manage database connections","Automate data archiving and deletion"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
